import { describe, it, expect } from 'vitest';
import {
  validateEmail,
  checkPasswordStrength,
  formatPhoneNumber,
} from '../src/validation';

describe('validateEmail', () => {
  describe('valid emails', () => {
    it('should accept standard email format', () => {
      const result = validateEmail('test@example.com');
      expect(result.isValid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    it('should accept email with subdomain', () => {
      const result = validateEmail('user@mail.example.com');
      expect(result.isValid).toBe(true);
    });

    it('should accept email with plus sign', () => {
      const result = validateEmail('user+tag@example.com');
      expect(result.isValid).toBe(true);
    });

    it('should accept email with numbers', () => {
      const result = validateEmail('user123@example123.com');
      expect(result.isValid).toBe(true);
    });

    it('should trim whitespace', () => {
      const result = validateEmail('  test@example.com  ');
      expect(result.isValid).toBe(true);
    });
  });

  describe('invalid emails', () => {
    it('should reject empty string', () => {
      const result = validateEmail('');
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Email is required');
    });

    it('should reject whitespace only', () => {
      const result = validateEmail('   ');
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Email is required');
    });

    it('should reject email without @', () => {
      const result = validateEmail('testexample.com');
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Invalid email format');
    });

    it('should reject email without domain extension', () => {
      const result = validateEmail('test@example');
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Email must have a valid domain');
    });

    it('should reject email with spaces', () => {
      const result = validateEmail('test @example.com');
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Invalid email format');
    });

    it('should handle null-like inputs', () => {
      const result = validateEmail(null as unknown as string);
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Email is required');
    });

    it('should handle undefined inputs', () => {
      const result = validateEmail(undefined as unknown as string);
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Email is required');
    });
  });
});

describe('checkPasswordStrength', () => {
  describe('weak passwords', () => {
    it('should identify empty password as weak', () => {
      const result = checkPasswordStrength('');
      expect(result.strength).toBe('weak');
      expect(result.score).toBe(0);
      expect(result.feedback).toContain('Password is required');
    });

    it('should identify short password as weak', () => {
      const result = checkPasswordStrength('abc');
      expect(result.strength).toBe('weak');
      expect(result.feedback).toContain('Password should be at least 8 characters');
    });

    it('should identify password without variety as weak', () => {
      const result = checkPasswordStrength('abcdefgh');
      expect(result.strength).toBe('weak');
    });

    it('should handle null input', () => {
      const result = checkPasswordStrength(null as unknown as string);
      expect(result.strength).toBe('weak');
      expect(result.feedback).toContain('Password is required');
    });
  });

  describe('medium passwords', () => {
    it('should identify password with mixed case as medium', () => {
      const result = checkPasswordStrength('Abcdefgh');
      expect(result.strength).toBe('medium');
    });

    it('should identify password with numbers as medium', () => {
      const result = checkPasswordStrength('abcdefg1');
      expect(result.strength).toBe('medium');
    });

    it('should identify decent password as medium', () => {
      const result = checkPasswordStrength('Abcdefg1');
      expect(result.strength).toBe('medium');
    });
  });

  describe('strong passwords', () => {
    it('should identify password with all criteria as strong', () => {
      const result = checkPasswordStrength('Abcdefg1!');
      expect(result.strength).toBe('strong');
      expect(result.score).toBeGreaterThanOrEqual(5);
    });

    it('should identify long complex password as strong', () => {
      const result = checkPasswordStrength('MyStr0ng!Pass');
      expect(result.strength).toBe('strong');
    });

    it('should have empty feedback for strong passwords', () => {
      const result = checkPasswordStrength('MyStr0ng!Pass');
      expect(result.feedback).toHaveLength(0);
    });
  });

  describe('feedback', () => {
    it('should suggest adding uppercase', () => {
      const result = checkPasswordStrength('abcdefgh1!');
      expect(result.feedback).toContain('Add uppercase letters');
    });

    it('should suggest adding lowercase', () => {
      const result = checkPasswordStrength('ABCDEFGH1!');
      expect(result.feedback).toContain('Add lowercase letters');
    });

    it('should suggest adding numbers', () => {
      const result = checkPasswordStrength('Abcdefgh!');
      expect(result.feedback).toContain('Add numbers');
    });

    it('should suggest adding special characters', () => {
      const result = checkPasswordStrength('Abcdefgh1');
      expect(result.feedback).toContain('Add special characters');
    });
  });
});

describe('formatPhoneNumber', () => {
