      expect(result.isValid).toBe(true);
      expect(result.formatted).toBe('(123) 456-7890');
    });

    it('should format number with parentheses', () => {
      const result = formatPhoneNumber('(123) 456-7890');
      expect(result.isValid).toBe(true);
      expect(result.formatted).toBe('(123) 456-7890');
