    it('should format 11-digit number with country code', () => {
      const result = formatPhoneNumber('11234567890');
      expect(result.isValid).toBe(true);
      expect(result.formatted).toBe('+1 (123) 456-7890');
    });

    it('should format number with +1 prefix', () => {
      const result = formatPhoneNumber('+1 123 456 7890');
      expect(result.isValid).toBe(true);
      expect(result.formatted).toBe('+1 (123) 456-7890');
    });
  });

  describe('international numbers', () => {
    it('should format 7-digit number', () => {
      const result = formatPhoneNumber('1234567');
      expect(result.isValid).toBe(true);
      expect(result.formatted).toBe('+1234567');
    });

    it('should format 15-digit number', () => {
      const result = formatPhoneNumber('123456789012345');
      expect(result.isValid).toBe(true);
      expect(result.formatted).toBe('+123456789012345');
    });
  });

  describe('invalid phone numbers', () => {
    it('should reject empty string', () => {
      const result = formatPhoneNumber('');
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Phone number is required');
    });

    it('should reject non-numeric input', () => {
      const result = formatPhoneNumber('abc');
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Phone number is required');
    });

    it('should reject too short number', () => {
      const result = formatPhoneNumber('123456');
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Invalid phone number format');
    });

    it('should reject too long number', () => {
      const result = formatPhoneNumber('1234567890123456');
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Invalid phone number format');
    });

    it('should handle null input', () => {
      const result = formatPhoneNumber(null as unknown as string);
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Phone number is required');
    });

    it('should handle undefined input', () => {
      const result = formatPhoneNumber(undefined as unknown as string);
      expect(result.isValid).toBe(false);
      expect(result.error).toBe('Phone number is required');
